SELECT clock_timestamp() AS db_at,p.id,p.operation_kind,p.idempotency_key,p.local_entity_id,p.state,p.error_code,p.confirmed_at,p.created_at,p.updated_at,(p.request_summary_json::json->'ozon_handoff_progress'->>'carriage_approved') AS carriage_approved FROM fbs_wb_operations p WHERE p.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND p.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND (p.local_entity_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' OR p.local_entity_id IN (SELECT o.id FROM fbs_orders o WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.marketplace='ozon')) ORDER BY p.created_at,p.id LIMIT 100
